  for (i=0; i<ndim; ++i) {
    casadi_int k, j;
    const casadi_real* g;
    casadi_real delta;
    g = grid + offset[i];
    j = index[i];
    delta =  g[j+1]-g[j];
    for (k=0;k<m;++k) grad[k] /= delta;
    grad += m;
  }
